/** 
 * Notifies all interested listeners that a <tt>ChatRoomMessageReceivedEvent</tt> has been fired.
 * @param message the received message
 * @param fromMember the <tt>ChatRoomMember</tt>, which is the sender of themessage
 * @param date the time at which the message has been received
 * @param eventType the type of the received event. One of theXXX_MESSAGE_RECEIVED constants declared in the <tt>ChatRoomMessageReceivedEvent</tt> class.
 */
public void fireMessageReceivedEvent(final Message message,final ChatRoomMember fromMember,final Date date,final int eventType){
  ChatRoomMessageReceivedEvent event=new ChatRoomMessageReceivedEvent(this,fromMember,date,message,eventType);
  Iterable<ChatRoomMessageListener> listeners;
synchronized (messageListeners) {
    listeners=new ArrayList<ChatRoomMessageListener>(messageListeners);
  }
  for (  ChatRoomMessageListener listener : listeners) {
    try {
      listener.messageReceived(event);
    } catch (RuntimeException e) {
      // Log exception and continue to next listener
    }
  }
}
